    v_pickColor = pickColor / 255.0;

    v_color = color;
    v_color.a *= alpha / 255.0 * show;

    v_st.s = texCoord;
    v_st.t = czm_writeNonPerspective(clamp(expandDir, 0.0, 1.0), gl_Position.w);

